module multi_pipe_8bit(
    input clk, rst_n, mul_en_in,
    input [7:0] mul_a, mul_b,
    output mul_en_out,
    output [15:0] mul_out
);
// TODO: Please add your logic design here
reg [3:0] mul_en_out_reg;
reg [7:0] mul_a_reg,mul_b_reg;
reg [15:0] sum[0:3];
reg [15:0] mul_out_reg;
wire [15:0] temp[0:7];
assign temp[0] = mul_b_reg[0]?{8'd0,mul_a_reg}:16'd0;
assign temp[1] = mul_b_reg[1]?{7'd0,mul_a_reg,1'd0}:16'd0;
assign temp[2] = mul_b_reg[2]?{6'd0,mul_a_reg,2'd0}:16'd0;
assign temp[3] = mul_b_reg[3]?{5'd0,mul_a_reg,3'd0}:16'd0;
assign temp[4] = mul_b_reg[4]?{4'd0,mul_a_reg,4'd0}:16'd0;
assign temp[5] = mul_b_reg[5]?{3'd0,mul_a_reg,5'd0}:16'd0;
assign temp[6] = mul_b_reg[6]?{2'd0,mul_a_reg,6'd0}:16'd0;
assign temp[7] = mul_b_reg[7]?{1'd0,mul_a_reg,7'd0}:16'd0;
always@(posedge clk or negedge rst_n)begin
    if(!rst_n)begin
        mul_en_out_reg <= 4'd0;
    end
    else begin
        mul_en_out_reg <= {mul_en_out_reg[2:0],mul_en_in};
    end
end
always@(posedge clk or negedge rst_n)begin
    if(!rst_n)begin
        mul_a_reg <= 8'd0;
        mul_b_reg <= 8'd0;
    end
    else if(mul_en_in)begin
        mul_a_reg <= mul_a;
        mul_b_reg <= mul_b;
    end
end
always@(posedge clk or negedge rst_n)begin
    if(!rst_n)begin
        sum[0] <= 16'd0;
        sum[1] <= 16'd0;
        sum[2] <= 16'd0;
        sum[3] <= 16'd0;
    end
    else begin
        sum[0] <= temp[0];
        sum[1] <= sum[0] + temp[1];
        sum[2] <= sum[1] + temp[2];
        sum[3] <= sum[2] + temp[3];
    end
end
always@(posedge clk or negedge rst_n)begin
    if(!rst_n)begin
        mul_out_reg <= 16'd0;
    end
    else begin
        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
    end
end
assign mul_out = mul_en_out_reg[3]?mul_out_reg:16'd0;
assign mul_en_out = mul_en_out_reg[3];
endmodule
